186			return false, 0, nil, wsProtocolError("close frame too large")
187		}
188		if opcode >= wsOpcodeClose && !fin {
189			return false, 0, nil, wsProtocolError("control frame must not be fragmented")
190		}
191		if length > wsMaxInboundMessage {
192			return false, 0, nil, wsProtocolError("frame too large")
193		}
194	
195		var mask [4]byte
196		if masked {
197			if _, err = io.ReadFull(c.br, mask[:]); err != nil {
198				return false, 0, nil, err
199			}
200		}
201		payload = make([]byte, length)
202		if length > 0 {
203			if _, err = io.ReadFull(c.br, payload); err != nil {
204				return false, 0, nil, err
205			}
206		}
207		if masked {
208			for i := range payload {
209				payload[i] ^= mask[i%4]
210			}
211		} else {
212			// RFC 6455 §5.1: a frame from a client MUST be masked.
213			return false, 0, nil, wsProtocolError("client frame is not masked")
214		}
215		return fin, opcode, payload, nil
216	}
217	
218	// ReadMessage returns the next complete data message, answering control
219	// frames inline: a ping is answered with a pong, a pong is ignored, and a
220	// close frame surfaces as ErrWebSocketClosed (the caller echoes it). Fragmented
221	// messages are reassembled in receive order.
222	func (c *wsConn) ReadMessage() (opcode byte, payload []byte, err error) {
223		var assembled []byte
224		started := false
225		messageOpcode := byte(wsOpcodeText)
226	
227		for {
228			fin, frameOpcode, framePayload, frameErr := c.readFrame()
229			if frameErr != nil {
230				return 0, nil, frameErr
231			}
232	
233			switch frameOpcode {
234			case wsOpcodeContinue:
235				if !started {
236					return 0, nil, wsProtocolError("continuation frame without a start frame")
237				}
238				assembled = append(assembled, framePayload...)
239			case wsOpcodeText, wsOpcodeBinary:
240				if started {
241					return 0, nil, wsProtocolError("new data frame before the fragment finished")
242				}
243				started = true
244				messageOpcode = frameOpcode
245				assembled = append(assembled[:0], framePayload...)
246			case wsOpcodeClose:
247				closeErr := parseClosePayload(framePayload)
248				if writeErr := c.writeCloseResponse(framePayload); writeErr != nil {
249					_ = c.conn.Close()
250				}
251				return 0, nil, closeErr
252			case wsOpcodePing:
253				if len(framePayload) > wsMaxControlPayload {
254					return 0, nil, wsProtocolError("ping payload too large")
255				}
256				if pingErr := c.writeControl(wsOpcodePong, framePayload); pingErr != nil {
257					return 0, nil, pingErr
258				}
259				continue
260			case wsOpcodePong:
261				continue
262			default:
263				return 0, nil, wsProtocolError(fmt.Sprintf("unknown opcode %d", frameOpcode))
264			}
265	
266			if len(assembled) > wsMaxInboundMessage {
267				return 0, nil, wsProtocolError("message too large")
268			}
269			if fin {
270				return messageOpcode, assembled, nil
271			}
272		}
273	}
274	
275	func parseClosePayload(payload []byte) error {
276		if len(payload) == 0 {
277			return &wsCloseError{Code: wsCloseGoingAway, Reason: ""}
278		}
279		if len(payload) < 2 {
280			return wsProtocolError("close payload too short")
281		}
282		code := int(binary.BigEndian.Uint16(payload[:2]))
283		return &wsCloseError{Code: code, Reason: string(payload[2:])}
284	}
285	
286	// writeFrame sends one server frame; server frames are never masked.
287	func (c *wsConn) writeFrame(opcode byte, fin bool, payload []byte) error {
288		_ = c.conn.SetWriteDeadline(time.Now().Add(wsWriteTimeout))
289	
290		var b0 byte = opcode
291		if fin {
292			b0 |= wsFlagFin
293		}
294	
295		var header [10]byte
296		header[0] = b0
297		n := 1
298		switch {
299		case len(payload) <= 125:
300			header[1] = byte(len(payload))
301			n++
302		case len(payload) <= 65535:
303			header[1] = 126
304			binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)))
305			n += 3
306		default:
307			header[1] = 127
308			binary.BigEndian.PutUint64(header[2:10], uint64(len(payload)))
309			n += 9
310		}
311		if _, err := c.conn.Write(header[:n]); err != nil {
312			return err
313		}
314		if len(payload) > 0 {
315			if _, err := c.conn.Write(payload); err != nil {
316				return err
317			}
318		}
319		return nil
320	}
321	
322	func (c *wsConn) writeControl(opcode byte, payload []byte) error {
323		c.writeMu.Lock()
324		defer c.writeMu.Unlock()
325		return c.writeFrame(opcode, true, payload)
326	}
327	
328	// WriteText sends one complete text frame.
329	func (c *wsConn) WriteText(payload []byte) error {
330		c.writeMu.Lock()
331		defer c.writeMu.Unlock()
332		if c.sentClose {
333			return errors.New("write after close frame")
334		}
335		return c.writeFrame(wsOpcodeText, true, payload)
336	}
337	
338	// writeCloseResponse echoes a client close frame when the server has not yet
339	// sent its own; it is the read-pump side of the closing handshake.
340	func (c *wsConn) writeCloseResponse(payload []byte) error {
341		c.writeMu.Lock()
342		defer c.writeMu.Unlock()
343		if c.sentClose {
344			return nil
345		}
346		c.sentClose = true
347		return c.writeFrame(wsOpcodeClose, true, payload)
348	}
349	
350	// Close sends the closing handshake with code/reason exactly once. It does not
351	// block on the peer's echo and never reads: the handler owns one read pump,
352	// and concurrent readers on the buffered connection are unsafe. The handler
353	// waits on its read pump and then calls NetClose.
354	func (c *wsConn) Close(code int, reason string) error {
355		c.writeMu.Lock()
356		defer c.writeMu.Unlock()
357		if c.sentClose {
358			return nil
359		}
360		c.sentClose = true
361		payload := make([]byte, 2+len(reason))
362		binary.BigEndian.PutUint16(payload, uint16(code))
363		copy(payload[2:], reason)
364		return c.writeFrame(wsOpcodeClose, true, payload)
365	}
366	
367	// NetClose drops the underlying TCP connection. The read pump unblocks with a
368	// read error; a double close (read pump and handler) is harmless.
369	func (c *wsConn) NetClose() error { return c.conn.Close() }
370	
371	type wsProtocolErrorString struct{ msg string }
372	
373	func (e *wsProtocolErrorString) Error() string { return "websocket protocol error: " + e.msg }
374	
375	func wsProtocolError(msg string) error { return &wsProtocolErrorString{msg: msg} }
376

